}{ "entries": [] }{"entries":[{"dz":"DZ149","name_han":"修真太極混元圖","name_vi":"Tu Chân Thái Cực Hỗn Nguyên Đồ","bu":"洞真","author":"蕭道存","era":"宋","topic":"cultivation","essence":"Sách đồ giải nội đan thời Tống, lấy hình Thái Cực–Hỗn Nguyên để chỉ đường luyện kim đan. Nhấn mạnh khí hóa ngũ tạng, phối âm dương và hỏa hầu theo đồ. Thuộc hệ sơ đồ tu chân gắn với truyền thừa Hoa Dương/thiên Thai.","key_text":"今作是圖，私自生歡。","use":"Đối chiếu sơ đồ khí huyết–đan điền khi học nội đan Nam Tông; tra hỏa hầu theo tháng.","sources":["https://zh.daoinfo.org/index.php?title=%E4%BF%AE%E7%9C%9F%E5%A4%AA%E6%A5%B5%E6%B7%B7%E5%85%83%E5%9C%96","https://www.shidianguji.com/zh/book/DZ0149","https://ctext.org/wiki.pl?if=gb&res=163685"],"textual_certainty":"high"},{"dz":"DZ150","name_han":"修真太極混元指玄圖","name_vi":"Tu Chân Thái Cực Hỗn Nguyên Chỉ Huyền Đồ","bu":"洞真","author":"不著撰人（宋）","era":"宋","topic":"cultivation","essence":"Bộ đồ quyết nội đan không đề tên tác giả, nghi đời Tống. Gồm các đồ thai tức, long hổ giao cấu, chu thiên hỏa hầu, trửu hậu phi kim tinh. Lấy ngũ tạng khí hóa và chu thiên vận hỏa làm trục.","key_text":"秘傳胎息訣有五門自然胎息訣第一。","use":"Học sơ đồ thai tức–hỏa hầu; đối chiếu với hệ Zhong-Lü/Nam Tông.","sources":["https://zh.daoinfo.org/index.php?title=%E4%BF%AE%E7%9C%9F%E5%A4%AA%E6%A5%B5%E6%B7%B7%E5%85%83%E6%8C%87%E7%8E%84%E5%9C%96","https://baike.baidu.com/item/%E4%BF%AE%E7%9C%9F%E5%A4%AA%E6%9E%81%E6%B7%B7%E5%85%83%E6%8C%87%E7%8E%84%E5%9B%BE/952326","https://www.jstor.org/stable/26768560"],"textual_certainty":"high"},{"dz":"DZ151","name_han":"金液還丹印證圖","name_vi":"Kim Dịch Hoàn Đan Ấn Chứng Đồ","bu":"洞真","author":"龍眉子","era":"南宋（序嘉定戊寅/1218）","topic":"cultivation","essence":"Sách đồ–thi ca nội đan của Long Mi Tử, tự thuật theo chỉ thầy, vẽ ngoại pháp tượng và nội pháp tượng. Giải chì–thủy ngân, hòa hợp, chân thổ, thủ thái, ôn dưỡng theo thứ tự tạo đan. Là bản đồ kinh điển của nam tông kim dịch hoàn đan.","key_text":"鉛汞明分兩，故有和合焉。和合成黃芽，故有真土焉。","use":"Đọc song song với Ngộ Chân thiên; dùng làm checklist thuật ngữ và thứ tự công phu.","sources":["https://fabriziopregadio.com/files/PREGADIO_and_ESPOSITO_Daozang_jiyao_Catalogue.pdf","https://ctext.org/wiki.pl?if=gb&res=863006","https://www.shidianguji.com/book/DZ0151"],"textual_certainty":"high"},{"dz":"DZ152","name_han":"修真歷驗鈔圖","name_vi":"Tu Chân Lịch Nghiệm Sao Đồ","bu":"洞真","author":"不著撰人（宋）","era":"宋","topic":"cultivation","essence":"Một quyển gồm mười hai đồ, mỗi đồ kèm luận ngắn về thái dược và hỏa hầu theo mười hai tháng. Mang tính lịch nghiệm–sao đồ, gần hệ Zhong-Lü/nam tông. Dùng để khóa nhịp luyện theo lịch tháng.","key_text":"集為圖論……略述十二月煉丹之採藥、火候要訣。","use":"Lập lịch hỏa hầu theo tháng; so với truyền đạo–bí pháp.","sources":["https://zh.daoinfo.org/index.php?title=%E4%BF%AE%E7%9C%9F%E6%AD%B7%E9%A9%97%E9%88%94%E5%9C%96","https://www.jstor.org/stable/26768560","https://crta.info/wiki/Daozang_-_DZ"],"textual_certainty":"high"},{"dz":"DZ153","name_han":"龍虎手鑑圖","name_vi":"Long Hổ Thủ Giám Đồ","bu":"洞真","author":"不著撰人","era":"宋–元","topic":"cultivation","essence":"Sách linh đồ nội đan lấy long–hổ làm pháp tượng, chỉ dẫn giao cấu, thăng giáng và giám định chân–giả. Nằm cụm linh đồ cùng các bản tu chân thái cực, kim dịch ấn chứng.","key_text":"null","use":"Tra pháp tượng long hổ khi đọc đan kinh nam tông.","sources":["https://www.jstor.org/stable/26768560","https://crta.info/wiki/Daozang_-_DZ","https://brill.com/display/book/9781684175161/BP000011.pdf"],"textual_certainty":"partial"},{"dz":"DZ155","name_han":"三才定位圖","name_vi":"Tam Tài Định Vị Đồ","bu":"洞真","author":"張商英等系（傳）","era":"北宋–南宋","topic":"philosophy","essence":"Đồ vũ trụ định vị thiên–địa–nhân, các tầng trời và ngôi vị thần tiên. Thuộc linh đồ vũ trụ luận, thường gắn với tấu trình triều Tống. Hữu ích cho phổ lục vị nghiệp và nghi thức bố trí thần vị.","key_text":"null","use":"Đối chiếu hệ tầng thiên giới và thần vị khi học phổ lục/linh đồ.","sources":["https://crta.info/wiki/Daozang_-_DZ","https://brill.com/display/book/9781684175161/BP000011.pdf","https://dokumen.pub/picturing-the-true-form-daoist-visual-culture-in-traditional-china-0674065735-9780674065734.html"],"textual_certainty":"high"},{"dz":"DZ156","name_han":"上清洞真九宮紫房圖","name_vi":"Thượng Thanh Động Chân Cửu Cung Tử Phòng Đồ","bu":"洞真","author":"上清系（不著撰人）","era":"六朝–唐宋傳本","topic":"cultivation","essence":"Đồ tồn tưởng thượng thanh về cửu cung và tử phòng trong thân/thiên. Chỉ dẫn vị trí cung thất, thần tồn và lộ trình thăng hư. Là chìa khóa thị giác cho hành pháp thượng thanh.","key_text":"null","use":"Học tồn tưởng cửu cung–tử phòng; đối chiếu với đại động/hoàng đình.","sources":["https://crta.info/wiki/Daozang_-_DZ","https://brill.com/display/book/9789004271647/B9789004271647_017.pdf","https://dokumen.pub/picturing-the-true-form-daoist-visual-culture-in-traditional-china-0674065735-9780674065734.html"],"textual_certainty":"high"},{"dz":"DZ683","name_han":"道德真經解","name_vi":"Đạo Đức Chân Kinh Giải","bu":"太玄","author":"陳象古","era":"宋","topic":"classic","essence":"Chú giải Đạo Đức chân kinh đời Tống của Trần Tượng Cổ, hai quyển, kinh văn không chia chương để nhấn mạnh đạo–đức hòa đồng. Lấy phục quy tự nhiên, thanh tịnh làm tông chỉ.","key_text":"道本真淳，理貴清淨。","use":"Đối chiếu chú Lão học Tống với các bản ngự chú/hội chú.","sources":["https://zh.daoinfo.org/index.php?title=%E9%81%93%E5%BE%B7%E7%9C%9F%E7%B6%93%E8%A7%A3%EF%BC%88%E9%99%B3%E8%B1%A1%E5%8F%A4%EF%BC%89","https://ctext.org/wiki.pl?if=gb&res=163933","https://crta.info/wiki/Daozang_-_DZ"],"textual_certainty":"high"},{"dz":"DZ687","name_han":"道德真經三解","name_vi":"Đạo Đức Chân Kinh Tam Giải","bu":"太玄","author":"鄧錡（玉賓子）","era":"元","topic":"classic","essence":"Chú Lão học nội đan đời Nguyên: mỗi chương giải theo ba lớp kinh–đạo–đức. Kết hợp nam tông (truyền Bạch Ngọc Thiềm) và toàn chân, lấy chân thường–tâm tính–đan pháp giải Lão. Kèm tự thuật đạo thống từ nguyên thủy đến bắc thất chân.","key_text":"太上老君，四極真人也。太者，大之極。上者，高之極。老者，壽之極。君者，人之極。","use":"Nghiên cứu Lão học toàn chân/nam tông; so với hội nguyên của Lý Đạo Thuần.","sources":["https://crta.info/wiki/Daozang_-_DZ","https://zh.daoinfo.org/index.php?title=%E9%81%93%E5%BE%B7%E7%9C%9F%E7%B6%93%E4%B8%89%E8%A7%A3%EF%BC%88%E9%84%A7%E9%8C%A1%EF%BC%89","https://zh.wikisource.org/wiki/%E9%81%93%E5%BE%B7%E7%9C%9F%E7%B6%93%E4%B8%89%E8%A7%A3","https://ctext.org/wiki.pl?if=gb&chapter=263633"],"textual_certainty":"high"},{"dz":"DZ702","name_han":"道德玄經原旨","name_vi":"Đạo Đức Huyền Kinh Nguyên Chỉ","bu":"太玄","author":"杜道堅","era":"元（約1294–1305）","topic":"classic","essence":"Bốn quyển chú Lão của Đỗ Đạo Kiên, nhấn mạnh nguyên chỉ huyền học, trị thân–trị quốc và đức tính thượng đức bất đức. Thuộc Lão học đạo sĩ Giang Nam đời Nguyên, ảnh hưởng lớn tới chú sớ đạo giáo.","key_text":"上德不德，是以有德。","use":"Đọc chú Lão Nguyên đại; tra khái niệm thượng đức/hạ đức.","sources":["http://www.chinaknowledge.de/Literature/Daoists/daozang.html","https://www.jstor.org/stable/26768560","https://zh.daoinfo.org/index.php?title=%E9%81%93%E5%BE%B7%E7%8E%84%E7%B6%93%E5%8E%9F%E6%97%A8%EF%BC%88%E6%9D%9C%E9%81%93%E5%A0%85%EF%BC%89","https://zh.wikisource.org/wiki/%E9%81%93%E5%BE%B7%E7%8E%84%E7%B6%93%E5%8E%9F%E6%97%A8"],"textual_certainty":"high"},{"dz":"DZ703","name_han":"玄經原旨發揮","name_vi":"Huyền Kinh Nguyên Chỉ Phát Huy","bu":"太玄","author":"杜道堅","era":"元","topic":"classic","essence":"Phần phát huy đi kèm Nguyên chỉ của Đỗ Đạo Kiên, triển khai sâu thêm nghĩa lý huyền kinh. Làm cầu nối giữa chú giải chương cú và diễn nghĩa triết–tu dưỡng.","key_text":"null","use":"Đọc sau Nguyên chỉ để nắm hệ Lão học Đỗ Đạo Kiên.","sources":["https://www.jstor.org/stable/26768560","http://www.chinaknowledge.de/Literature/Daoists/daozang.html","https://a.daorenjia.com/c15"],"textual_certainty":"high"},{"dz":"DZ714","name_han":"道德真經藏室纂微篇","name_vi":"Đạo Đức Chân Kinh Tàng Thất Toản Vi Thiên","bu":"太玄","author":"陳景元（碧虛子）","era":"北宋","topic":"classic","essence":"Mười quyển toản chú của Trần Cảnh Nguyên, tập hợp nghĩa vi diệu từ nhiều nhà chú Lão. Lấy hư tâm đãi vật, thường đạo làm tông, là cột mốc Lão học đạo giáo Bắc Tống.","key_text":"上篇明道以常道為宗。常道者，虛心以待物者也。","use":"Tra cứu chú sớ Lão học Tống; so với huyền đức toản sớ và các bản tập chú.","sources":["http://www.chinaknowledge.de/Literature/Daoists/daozang.html","https://zh.daoinfo.org/index.php?title=%E9%81%93%E5%BE%B7%E7%9C%9F%E7%B6%93%E8%97%8F%E5%AE%A4%E7%BA%82%E5%BE%AE%E7%AF%87%EF%BC%88%E9%99%B3%E6%99%AF%E5%85%83%EF%BC%89","https://ctext.org/library.pl?if=gb&res=84392","https://ctext.org/wiki.pl?if=en&chapter=965298"],"textual_certainty":"high"},{"dz":"DZ1046","name_han":"悟玄篇","name_vi":"Ngộ Huyền Thiên","bu":"太玄","author":"余洞真","era":"南宋（序1229）","topic":"cultivation","essence":"Thiên luận nội đan của Dư Động Chân, bàn hình hóa–khí hóa và đường vào huyền. Ngắn gọn, thiên về chỉ thuật công phu và nhận thức huyền cơ.","key_text":"null","use":"Nhập môn thuật ngữ nội đan Nam Tống; đọc kèm các thiên ngộ chân.","sources":["https://crta.info/wiki/Daozang_-_DZ","https://fabriziopregadio.com/files/PREGADIO_and_ESPOSITO_Daozang_jiyao_Catalogue.pdf","https://neidanwiki.com/index.php?title=Wuxuan_pian_%E6%82%9F%E7%8E%84%E7%AF%87","https://www.jstor.org/stable/26768560"],"textual_certainty":"high"},{"dz":"DZ1071","name_han":"原陽子法語","name_vi":"Nguyên Dương Tử Pháp Ngữ","bu":"太玄","author":"趙宜真（原陽子）","era":"元末明初","topic":"cultivation","essence":"Ngữ lục–pháp ngữ của Triệu Nghi Chân, trộn nội đan, đạo pháp và khuyến tu. Gồm ca kệ hoàn đan, tụng chân đạo quy nhất và đối đáp với các luyện sư. Phản ánh giao thoa toàn chân–thanh vi–tịnh minh.","key_text":"null","use":"Nghiên cứu pháp ngữ cuối Nguyên đầu Minh; đối chiếu với linh bảo quy không quyết.","sources":["https://crta.info/wiki/Daozang_-_DZ","https://www.jstor.org/stable/26768560","https://ctext.org/wiki.pl?if=gb&res=533229"],"textual_certainty":"high"},{"dz":"DZ1072","name_han":"金丹直指","name_vi":"Kim Đan Trực Chỉ","bu":"太玄","author":"周無所住","era":"南宋（序淳祐庚戌/1250）","topic":"cultivation","essence":"Một quyển gồm mười sáu tụng và đáp vấn, trực chỉ nam tông kim đan. Chịu ảnh hưởng Thiền, nhấn mạnh thân làm lô đỉnh, dược tại bản thân, tránh chi chi tiết rườm rà.","key_text":"爐鼎以身譬者。","use":"Học khẩu quyết ngắn gọn nam tông; so với kim đan vấn đáp trong tu chân thập thư.","sources":["https://crta.info/wiki/Daozang_-_DZ","https://brill.com/display/book/edcoll/9789004271647/B9789004271647_027.pdf","https://homeinmists.ilotus.org/DaoZang/Tiyao5.pdf"],"textual_certainty":"high"},{"dz":"DZ1257","name_han":"群仙要語纂集","name_vi":"Quần Tiên Yếu Ngữ Toản Tập","bu":"正一","author":"董瑾醇（董漌醇）","era":"元–明","topic":"类书","essence":"Toản tập lời cốt yếu của quần tiên về tu luyện nội đan, hai quyển. Thuộc loại thư–tuyển yếu, tiện tra khẩu quyết và câu danh ngôn đan đạo. Bổ sung cho các tổng tập như chư chân nội đan tập yếu.","key_text":"null","use":"Tra cứu trích yếu tiên gia; làm mục lục ý tưởng cho lớp học nội đan.","sources":["https://crta.info/wiki/Daozang_-_DZ","https://www.jstor.org/stable/26768560","https://homeinmists.ilotus.org/%E9%81%93%E8%97%8F%E5%8C%AF%E7%B7%A8/%E6%AD%A3%E7%B5%B1%E9%81%93%E8%97%8F/%E9%81%93%E8%97%8F%E7%9B%AE%E9%8C%84/"],"textual_certainty":"high"},{"dz":"DZ1258","name_han":"諸真內丹集要","name_vi":"Chư Chân Nội Đan Tập Yếu","bu":"正一","author":"玄全子","era":"元","topic":"类书","essence":"Ba quyển tập yếu chư chân về nội đan do Huyền Toàn Tử biên. Gom ca kệ, khẩu quyết và chương yếu từ nhiều tiên gia, nhấn mạnh huyền tẫn, tính mệnh và bệnh của tu hành chỉ luyện mệnh.","key_text":"玄牝之門號金母，先天先地藏真土。","use":"Tuyển đọc cốt tủy nội đan đa nguồn; tra bệnh–dược của công phu.","sources":["https://crta.info/wiki/Daozang_-_DZ","https://zh.daoinfo.org/index.php?title=%E8%AB%B8%E7%9C%9F%E5%85%A7%E4%B8%B9%E9%9B%86%E8%A6%81","https://zh.wikisource.org/zh-hant/%E8%AB%B8%E7%9C%9F%E5%85%A7%E4%B8%B9%E9%9B%86%E8%A6%81"],"textual_certainty":"high"},{"dz":"DZ1465","name_han":"消搖墟經","name_vi":"Tiêu Dao Khư Kinh","bu":"续道藏","author":"洪自成（洪自誠）","era":"明（萬曆續道藏）","topic":"仙传","essence":"Hai quyển tiên truyện–tiểu dao chí thuộc Vạn Lịch tục đạo tạng, biên soạn bởi Hồng Tự Thành. Tập hợp hành trạng ẩn sĩ–chân tiên, mang màu phổ lục và tiêu dao chí. Bổ sung mảng phổ lục/tiên sử ít được phủ.","key_text":"蒙莊氏所稱消搖遊者，意在斯乎。","use":"Đọc tiểu sử tiên ẩn; đối chiếu với liệt tiên/lịch thế chân tiên.","sources":["https://crta.info/wiki/Daozang_-_DZ","https://www.jstor.org/stable/26768560","https://zh.wikisource.org/zh-hant/%E8%90%AC%E6%9B%86%E7%BA%8C%E9%81%93%E8%97%8F","http://www.ctcwri.idv.tw/CTCW-CMTS/CMT08%E7%BA%8C%E9%81%93%E8%97%8F/CNDZ08-ALL/CNDZ0835%E6%B6%88%E9%81%99%E5%A2%9F%E7%B6%93/CNDZ0835-1%E6%B6%88%E9%81%99%E5%A2%9F%E7%B6%93%E5%8D%B7%E4%B8%8A.htm"],"textual_certainty":"high"}]}
